      'beginner.res.gold.th.priority': '优先级',
      'beginner.res.gold.th.return': '回报',
      'beginner.res.gold.th.use': '用途',
      'beginner.res.h2': '什么值得花、什么不值得？',
      'beginner.res.intro': '游戏中有三种核心资源：许愿星（稀缺）、金币（可赚）、时间（有限）。每一类都有优先级——花对地方事半功倍。',
      'beginner.res.star.h3': '⭐ 许愿星消费优先级',
      'beginner.res.star.t1.h': '🥇 第一优先：背包 & 仓库扩容（前 5 次）',
      'beginner.res.star.t1.p': '前 5 次背包 +10 格、仓库 +50 格各仅需 <strong>10 许愿星</strong>（原价 25，相当于 4 折）。这是全游戏最值的投资——背包空间直接影响采集和钓鱼效率。找 NPC Ka Ching（西北郊区 8 号地块对面）购买。共需 <strong>100 星 = +50 背包 + 250 仓库</strong>。第 6 次起涨到 25 星/次，性价比骤降，暂时不要继续买。',
      'beginner.res.star.t2.h': '🥈 第二优先：爱好解锁 & 烹饪升级',
      'beginner.res.star.t2.p': '钓鱼(Lv.2 自动)、园艺(Lv.3 自动)不需要花许愿星。烹饪(Lv.5 用爱好扩展券)是第一个需要决策的——必选。后续捕虫(Lv.8)、观鸟(Lv.11)各需要一张扩展券。<strong>烹饪爱好等级越高 → 出高星概率越大 → 同样材料多赚 50-100%。</strong>',
      'beginner.res.star.t3.h': '🥉 第三优先：功能性建筑 & 家具',
      'beginner.res.star.t3.p': '额外炉灶（每多一个灶就能多同时做一道菜）、更多田地、功能性储物家具。这些直接提升赚钱效率，属于「花钱赚钱」的投资型消费。<strong>炉灶越多，能同时做的菜越多——从 1 灶到 4 灶，同样时间能做四倍。</strong>',
      'beginner.res.star.t4.h': '💡 应急用途 & 绝对不花的地方',
      'beginner.res.star.t4.p': '<strong>应急：</strong>许愿星换不到金币——1 星换的是彩光穿天猴，一次性消耗品、无转售价（"转手卖 1,100"查无实据）。许愿星比金币珍贵得多，留着升永久。<br><strong>❌ 绝对不要：</strong>加速作物生长（2 小时不值 1 星）、购买基础原料（种/钓/采集免费获得）、纯装饰物品（DG Lv.15 高级建造后再考虑）、加速宠物/爱好进度',
      'beginner.res.time.c1.h': '🔴 最高优先',
      'beginner.res.time.c1.p': '\n          <strong>每日 5 个居民任务</strong>（必做！）<br>\n          金币 + 许愿星 + 贡献勋章<br>\n          （金币数量不定，非固定值）<br>\n          <span style="color:var(--coral)">不可跳过，DG 经验唯一来源</span>\n        ',
      'beginner.res.time.c2.h': '🟡 高优先',
      'beginner.res.time.c2.p': '\n          <strong>四灶批量烹饪</strong><br>\n          4 灶同时开火，一次做 4 份<br>\n          效率比单灶高得多<br>\n          <strong>高价值点钓鱼</strong>（海洋）<br>\n          收益看具体鱼种\n        ',
      'beginner.res.time.c3.h': '🟢 中优先',
      'beginner.res.time.c3.p': '\n          <strong>免费采集扫荡</strong><br>\n          浆果、蘑菇、香草、水果<br>\n          完全免费——零成本<br>\n          <strong>低价值点钓鱼</strong>（河流·全年）<br>\n          效率：灵活，囤食材等烹饪\n        ',
      'beginner.res.time.h3': '⏰ 时间投入优先级',
