      'dbfish.help': '🐟 鱼类图鉴使用说明',
      'dbfish.helpText': '每一条鱼都标注了位置、天气、出没时间、稀有度和售价。按名称搜索或按稀有度筛选，规划好你的钓鱼行程。<strong>快速提示：</strong>售价超过 100 金币的鱼直接出售，便宜的留作烹饪材料；金枪鱼（850 金币）是全图鉴售价最高的鱼。',
      // 钓鱼攻略（鱼类图鉴标题下方）
      'dbfish.guide.eyebrow': '🎣 钓鱼攻略',
      'dbfish.guide.h2': '从入门到精通：<strong style="color:var(--teal)">钓鱼</strong>攻略',
      'dbfish.guide.intro': '下竿前你需要知道的一切：解锁条件、等级、钓点、天气，以及全岛最值钱的渔获。',
      'dbfish.guide.rules': '<strong>🎣 记住三条规则：</strong> ❶ DG 等级达到 2 级后，导师 Vanya 会主动赠送鱼竿并解锁钓鱼 &nbsp; ❷ 89 种鱼类分布在河流 / 湖泊 / 海洋三类水域 &nbsp; ❸ 超过 100 金币的鱼直接出售，其余留作烹饪',
      'dbfish.guide.g1.h': '🎣 解锁与第一根鱼竿',
      'dbfish.guide.g1.p': 'DG 等级达到 2 级后，导师 Vanya 会自动登门拜访、赠送鱼竿，并解锁钓鱼——你的第一个生产类爱好。',
      'dbfish.guide.g2.h': '📈 钓鱼等级 1–10',
      'dbfish.guide.g2.p': '通过钓鱼提升等级。许多稀有鱼种都有等级门槛——北极红点鲑和蓝鳃太阳鱼需要 10 级，多瑙哲罗鱼需要 9 级。',
      'dbfish.guide.g3.h': '🎯 看鱼影识鱼',
      'dbfish.guide.g3.p': '鱼影大小提示渔获：S / M / L 对应普通鱼，<strong>金色</strong>鱼影对应稀有高价值鱼种，蓝色鱼影对应特殊渔获。',
      'dbfish.guide.w.h3': '去哪儿钓',
      'dbfish.guide.river.h': '🏞️ 河流与池塘',
      'dbfish.guide.river.p': '浅滩河（鲃鱼）、静谧河（江鱈与鲑鱼）、巨树河（多瑙哲罗鱼）与 Rosy 河各有特色鱼种。',
      'dbfish.guide.lake.h': '🌿 湖泊',
      'dbfish.guide.lake.p': 'Meadow 湖是最佳新手钓点（金鱼、胡瓜鱼、蝴蝶锦鲤）。森林湖（鲈鱼、北极红点鲑）、郊区湖（鲫鱼）与温泉山湖（蓝鳃太阳鱼）也各有特色。',
      'dbfish.guide.sea.h': '🌊 海洋',
      'dbfish.guide.sea.p': '渔村码头是日常海钓首选（鲑鱼、沙丁鱼）。鲸海、Zephyr 海（带鱼）、东海与古海各有独特的渔获。',
      'dbfish.guide.wst.h3': '天气 · 季节 · 时间',
      'dbfish.guide.weather.h': '🌦️ 天气',
      'dbfish.guide.weather.p': '雨天和彩虹天气会解锁稀有鱼种——黄金帝王蟹等鱼<strong>只在彩虹天气</strong>出现。晴天适合钓许多海鱼。',
      'dbfish.guide.season.h': '🍂 季节',
      'dbfish.guide.season.p': '心托邦的鱼类大多全年可钓——季节不是限制因素，天气和出没时间才是。出发前对照图鉴里的具体天气与时间段即可。',
      'dbfish.guide.time.h': '🌙 时间',
