      'dbbirds.guide.h2': '从入门到精通：<strong style="color:var(--lavender)">观鸟</strong>攻略',
      'dbbirds.guide.intro': '举起望远镜之前你需要知道的一切：解锁、升级、栖息地、天气，以及最值得追的稀有物种。',
      'dbbirds.guide.rules': '<strong>🔭 记住三条规则：</strong> ❶ DG 等级达到 11 级后，用爱好扩展券找 Bailey J 解锁观鸟 &nbsp; ❷ 观鸟等级决定哪些鸟会出现 &nbsp; ❸ 重复拍摄同一只鸟也能累积升级进度',
