      'dbbirds.guide.water.h': '🌊 水边与海岸',
      'dbbirds.guide.water.p': '鲸海（奥氏鸥）、东海/和风海（帝鸬鹚）、古海海边（褐燕鸥）、紫光海滩（白鹡鸰）和森林湖（斑头秋沙鸭）覆盖了水鸟和海鸟。',
      'dbbirds.guide.mountain.h': '⛰️ 山地与花田',
      'dbbirds.guide.mountain.p': '温泉山（欧亚雕鸮、大山雀、锡嘴雀）和花田（苍头燕雀、橙腹果鸠、美洲火烈鸟）栖息着许多独特物种。',
      'dbbirds.guide.wst.h3': '天气 · 时间 · 稀有度',
      'dbbirds.guide.weather.h': '🌦️ 天气',
