      'dbrecipes.guide.hv.r7.name': '精致下午茶宴', 'dbrecipes.guide.hv.r7.unlock': '烹饪 12 级 · Massimo 商店',
      'dbrecipes.guide.hv.r8.name': '黑松露奶油意面', 'dbrecipes.guide.hv.r8.unlock': '烹饪 11 级 · Massimo 商店',
      'dbrecipes.guide.hv.r9.name': '起司虾仁炸虾钳', 'dbrecipes.guide.hv.r9.unlock': '烹饪 13 级 · Massimo 商店',
      'dbrecipes.guide.rule.h': '🥫 利润法则：先加工，别卖原材料',
      'dbrecipes.guide.rule.p': '<strong>永远别把廉价食材直接卖掉。</strong>4 颗蓝莓（64 金币）能做成蓝莓酱（170–340 金币），任意廉价鱼加土豆能做成炸鱼薯条（310–620 金币）——同样的食材，利润翻 2–5 倍。超过 100 金币的高价鱼直接卖，更便宜的留作烹饪。唯一例外：帝王蟹清蒸（1990 金币）比生卖（535 金币）划算得多。',
      'dbrecipes.guide.tip.h': '🚀 进阶技巧',
      'dbrecipes.guide.t1.h': '🫐 采集蓝莓做酱',
      'dbrecipes.guide.t1.p': '蓝莓是采集品、无法种植——白天跑图顺手采集灌木丛，做成蓝莓酱（170 金币+），形成零成本的完美循环。',
      'dbrecipes.guide.t2.h': '🔥 四灶批量烹饪',
      'dbrecipes.guide.t2.p': '让 4 口炉灶同时做同一种菜——蓝莓酱、炸鱼薯条或草莓酱——无需额外操作即可成倍产出。',
      'dbrecipes.guide.t3.h': '📅 别错过活动食谱',
      'dbrecipes.guide.t3.p': '寻鲸季料理（海洋盛宴 1600 金币）、三丽鸥联动可丽饼（扭蛋机）以及隐藏的雏菊花茶 / 玫瑰花茶都是限时的，趁活动期间抓紧解锁。',
      'dbrecipes.help': '🍳 食谱大全使用说明',
      'dbrecipes.helpText': '每道食谱都列出了材料、能量、售价和净利润，方便你比较哪些菜值得批量烹饪。按利润率排序即可找到每天最赚钱的菜。<strong>快速提示：</strong>草莓酱（1580 金币）和炸鱼薯条（310 金币）是每日批量首选，清蒸黄金帝王蟹则以 2980 金币位居售价榜首。',
      'dbcrops.help': '🌱 作物图鉴使用说明',
      'dbcrops.helpText': '对比 18 种作物的生长时间、解锁条件和每小时收益，规划最高效的农田；优先级一栏标出了最佳种植选择。<strong>快速提示：</strong>土豆（90 金币/1 小时）前期收益是番茄的 3 倍，睡前种小麦（4 小时）或生菜（8 小时）醒来正好收。',
      // 作物攻略（作物图鉴标题下方）
      'dbcrops.guide.eyebrow': '🌱 作物攻略',
      'dbcrops.guide.h2': '从入门到精通：<strong style="color:var(--green)">种田</strong>攻略',
      'dbcrops.guide.intro': '播下第一颗种子前你需要知道的一切：解锁条件、农耕等级、季节适配、浇水机制，以及全岛最值钱的作物。',
      'dbcrops.guide.rules': '<strong>🌱 记住三条规则：</strong> ❶ DG 等级达到 3 级后，导师 Blanc 解锁园艺 &nbsp; ❷ 雨天会自动浇水 &nbsp; ❸ 便宜的作物加工成料理——蓝莓和土豆价值能翻 3–5 倍',
      'dbcrops.guide.g1.h': '🌱 解锁与第一批种子',
      'dbcrops.guide.g1.p': 'DG 等级达到 3 级后，导师 Blanc（城镇中心附近）解锁园艺。先买土豆种子——新手期最佳作物，收益是番茄的 3 倍。',
      'dbcrops.guide.g2.h': '📈 看懂生长时间',
      'dbcrops.guide.g2.p': '土豆 1 小时熟（白天可轮作多轮），番茄 15 分钟（全游戏最快），小麦 4 小时、生菜 8 小时（适合睡前种）。合理安排播种时间，让作物在你起床时正好成熟。',
      'dbcrops.guide.g3.h': '🎯 优先级一栏',
      'dbcrops.guide.g3.p': '图鉴标出了最佳种植选择——<strong>最高</strong>（土豆、小麦、草莓）、<strong>高</strong>（番茄、生菜、菠萝、葡萄）与<strong>中</strong>（玉米、胡萝卜等）。优先种高优先级作物赚钱，再留几样便宜作物当任务储备。',
      'dbcrops.guide.w.h3': '该种什么',
      'dbcrops.guide.grain.h': '🌾 谷物',
      'dbcrops.guide.grain.p': '小麦（4 小时、285 金币）是基础——几乎所有高利润食谱都需要，园艺 Lv.2 起批量种植。玉米（12 小时、515 金币）适合睡前种。',
      'dbcrops.guide.veg.h': '🥔 蔬菜',
      'dbcrops.guide.veg.p': '土豆是前期赚钱之王（90 金币、1 小时、常驻可种）。番茄（30 金币）和生菜（435 金币）是任务与烹饪的常用填充；胡萝卜（155 金币）和茄子（406 金币）是中期稳定作物。',
      'dbcrops.guide.fruit.h': '🍓 水果与采集',
      'dbcrops.guide.fruit.p': '蓝莓 → 果酱是经典利润循环（4 颗 → 170 金币以上）。草莓（375 金币）做成草莓酱值 1580 金币，是收益最高的加工路线；菠萝（52 金币、30 分钟）是快速轮作的水果。黑松露（99 金币）是野外采集的稀有品。',
      'dbcrops.guide.wst.h3': '季节 · 浇水 · 收获',
      'dbcrops.guide.season.h': '🍂 季节',
      'dbcrops.guide.season.p': '常驻作物全年可种，没有季节限制。活动限定作物（水稻、白萝卜、罗马生菜、杨桃、柠檬马鞭草）只在对应活动期间开放种植。',
      'dbcrops.guide.watering.h': '🌧️ 浇水与雨天',
      'dbcrops.guide.watering.p': '雨天会自动浇水——雨天可以省掉手动浇水。睡前看天气预报：雨夜意味着第二天醒来田地已浇好、作物可收。',
      'dbcrops.guide.harvest.h': '🧺 收获类型',
      'dbcrops.guide.harvest.p': '每株作物成熟后收获。快熟作物（番茄 15 分钟、土豆 1 小时）适合白天多轮播种，长线作物（生菜 8 小时、玉米 12 小时）适合睡前种。',
      'dbcrops.guide.hv.h3': '💰 高价值目标',
      'dbcrops.guide.hv.intro': '值得专门留一块地的作物——播种前先确认季节和解锁条件。',
