      'dbnpcs.guide.hv.r7.name': '琼夫人', 'dbnpcs.guide.hv.r7.role': '宠物领养', 'dbnpcs.guide.hv.r7.unlock': 'DG Lv.12', 'dbnpcs.guide.hv.r7.why': '解锁养猫（养狗需先完成猫护理教程）。宠物可换装、喂食、互动。',
