      'dbachievements.help': '🏆 成就列表使用说明',
      'dbachievements.helpText': '69 项成就按类别分组，标注了解锁条件、奖励和难度评级。按名称搜索或按类别浏览，规划你的达成路线。<strong>快速提示：</strong>优先完成钓鱼、园艺和烹饪类成就——它们奖励许愿星和称号，可以用来投入背包扩容。',
      // 成就攻略（成就图鉴标题下方）
      'dbachievements.guide.eyebrow': '🏆 成就攻略',
