      'faq.q31': '<span>💬</span>Dream Bubble（梦幻气泡）怎么触发？<span class="faq-arrow">▾</span>',
      'faq.q32': '<span>📋</span>主线任务卡进度 / 订单不刷新？<span class="faq-arrow">▾</span>',
      'faq.q33': '<span>🛒</span>"购买任意家具"任务无法完成？<span class="faq-arrow">▾</span>',
      'faq.q34': '<span>🐱</span>怎么养狗？我已经有猫了。<span class="faq-arrow">▾</span>',
      'faq.q35': '<span>🔓</span>宠物系统什么时候解锁？要什么条件？<span class="faq-arrow">▾</span>',
      'faq.q36': '<span>🐾</span>宠物卡在天花板或陷到地板下面了？<span class="faq-arrow">▾</span>',
      'faq.q37': '<span>🦙</span>野生动物（羊驼/鹿/水豚/狐狸）能收养吗？<span class="faq-arrow">▾</span>',
      'faq.q38': '<span>🍖</span>喂宠物什么食物最好？怎么快速加好感？<span class="faq-arrow">▾</span>',
      'faq.q39': '<span>🏪</span>宠物店品种不满意怎么办？能养几只？<span class="faq-arrow">▾</span>',
      'faq.q4': '<span>💾</span>游戏卡顿 / 掉帧严重？<span class="faq-arrow">▾</span>',
      'faq.q40': '<span>🎁</span>宠物会送礼物吗？好感度有什么用？<span class="faq-arrow">▾</span>',
      'faq.q41': '<span>🔗</span>怎么和好友联机？什么时候解锁？<span class="faq-arrow">▾</span>',
      'faq.q42': '<span>🏘️</span>怎么去好友的小镇？有什么限制？<span class="faq-arrow">▾</span>',
      'faq.q43': '<span>🏗️</span>好友能帮我一起建造吗？<span class="faq-arrow">▾</span>',
      'faq.q44': '<span>🔀</span>可以转服务器吗？和好友不同服怎么办？<span class="faq-arrow">▾</span>',
