      'money.fishing.c1.p': '<strong>125G 以下 → 烹饪材料。</strong>沙丁鱼 50、鲤鱼 65、鲫鱼 75、鲈鱼 75、海鲈鱼 75、小龙虾 100。<br><br><strong>125G 以上 → 原样卖掉。</strong>鲑鱼 150、江鳕 200、河豚 230、金鱼 250、鳗鱼 380。<br><br><span style="color:var(--coral)">只有两个例外：帝王蟹和黄金帝王蟹，它们的食谱吃三只同种蟹，做完还是赚。</span>',
      'money.fishing.c2.h': '🌧️ 雨夜是最好的窗口',
      'money.fishing.c2.p': '两种最值钱的淡水鱼条件一模一样——<strong>下雨、夜间</strong>：<br>🐟 <strong>鲶鱼 610</strong> · 池塘<br>🐍 <strong>鳗鱼 380</strong> · 河流<br><br>内陆没有别的能比。天黑之后开始下雨，手头的事放下去钓鱼。',
