      'money.fishing.estimate': '<strong>🎣 关于「钓鱼每小时多少金币」：</strong>本页原来写过一个数，我们把它删了。上钩速度取决于钓鱼等级、鱼竿、鱼饵和纯运气，我们没有办法测，写出来的任何数字都是编的。我们能告诉你的是每条鱼值多少、哪个食谱给的最多——那才是真正会改变你决策的部分。',
