      'money.star.intro': '许愿星买的是容量，而容量决定你能不能批量干活。除此之外关于它的说法，大多经不起查。',
      'money.star.priority.h3': '🏅 花费优先级',
      'money.star.priority.p1.h': '🥇 两种扩容的前五次买满，之后再想',
      'money.star.priority.p1.p': '背包扩容（+10 格）和仓库扩容（+50 格）的前五次，各只要 <strong>10 许愿星</strong>。第六次起是 <strong>25 星</strong>——而且就一直停在 25，不会继续涨。<br><span style="color:var(--green)">100 星换 +50 背包和 +250 仓库。这是全游戏最划算的一档，而且过了就没有了。</span>',
      'money.star.priority.p2.h': '🥈 DG 白送的别花钱买',
      'money.star.priority.p2.p': '仓库会在 <strong>DG Lv.2、7、13、17、19</strong> 自动扩容——每次 +50 格，共 +250，不花一分钱。免费上限是 <strong>400 格</strong>。<br><span style="color:var(--green)">背包基础容量也随 DG 自己长，Lv.1 大约 20 格，到 Lv.20 约 52 格。花星之前先看看后面有什么。</span>',
      'money.star.priority.p3.h': '🥉 爱好不是用星买的',
      'money.star.priority.p3.p': '钓鱼在 <strong>DG Lv.2</strong> 开，园艺在 <strong>DG Lv.3</strong> 开。再往后的新爱好靠<strong>爱好扩展券，在 DG Lv.5、8、11 各发一张</strong>——七个爱好，只有三张券。<br><span style="color:var(--green)">第一张券给烹饪。它是唯一能把另外两个爱好的产出翻倍的。</span>',
      'money.star.priority.p4.h': '⚠️ 一个并不存在的流行技巧',
      'money.star.priority.p4.p': '你会看到攻略说 1 个许愿星买个冲天炮转手卖 1,100 金币。<strong>我们找不到任何佐证。</strong>1 星确实能换一个彩光穿天猴，但那是一次性消耗品，没有这个转售价。本页在核查之前也一直写着这条；现在删了。',
