      'money.sub': '本页每一个价格都直接取自我们自建的作物、鱼类与食谱数据库——没有估算收入，没有拿不出出处的数字',
      'money.tips.c1.h': '⭐ 烹饪等级比选食谱重要',
      'money.tips.c1.p': '★★ 给 1.5 倍、★★★ 给 2 倍基础价，94 个食谱无一例外。把一道菜从 ★ 做到 ★★★，比换一道更花哨的菜赚得多，而且不多花一样材料。',
      'money.tips.c2.h': '🌾 常留一块地给小麦',
      'money.tips.c2.p': '94 个食谱里 25 个要小麦——披萨、派、意面、蛋糕、贝果、烩饭。它 47.5 的时薪只算中游，但断货卡住的食谱比任何别的材料都多。',
      'money.tips.c3.h': '🐟 鱼的分界线是 125，不是 100',
      'money.tips.c3.p': '炸鱼薯条吃 2 条鱼 2 个土豆卖 310。土豆按 30G 的种子价算，鱼价超过 125G 下锅就不划算了；土豆按 90G 的售价算，这条线降到 65G。',
      'money.tips.c4.h': '🦀 帝王蟹三只一存',
      'money.tips.c4.p': '清蒸帝王蟹只要三只帝王蟹，别的什么都不要：1,605 的生鱼变成 1,990，★★★ 是 3,980。黄金版吃三只黄金帝王蟹，原价 2,250，卖 2,980。',
      'money.tips.c5.h': '🚫 葡萄和可可豆千万别做酱',
      'money.tips.c5.p': '4 颗葡萄原样卖 1,920，葡萄酱卖 220。4 颗可可豆 1,320，巧克力酱 240。两者就算出 ★★★ 也还在水下。水果直接卖。',
      'money.tips.c6.h': '🍍 回报最高的果酱是菠萝',
      'money.tips.c6.p': '4 颗菠萝种子 60，酱卖 280——按掏出去的钱算回报 367%，是我们能完整定价的项目里最高的。菠萝还只要 30 分钟就熟。',
      'money.tips.c7.h': '🌧️ 天黑下雨就去钓鱼',
      'money.tips.c7.p': '鲶鱼（610，池塘）和鳗鱼（380，河流）都要求下雨和夜间同时成立。它们是内陆最值钱的两种鱼，窗口窄到大多数人根本没撞上过。',
