      'privacy.s1.p2': '<strong>Cookie 和追踪技术</strong>——我们可能会使用 Cookie、网络信标和类似的追踪技术来收集有关您浏览活动的信息。您可以通过浏览器设置来控制 Cookie。',
      'privacy.s10.h2': '10. 免责声明',
