      'privacy.s3.h2': '3. 第三方服务',
      'privacy.s3.li1': '<strong>Google Analytics</strong>：我们使用 Google Analytics 来了解访问者如何与我们的网站互动。Google Analytics 匿名收集信息并报告网站趋势，不会识别单个访问者。',
      'privacy.s3.li2': '<strong>Google AdSense</strong>：我们使用 Google AdSense 投放广告。Google 及其合作伙伴使用广告 Cookie（包括 DoubleClick cookie），根据您此前对本网站及其他网站的访问记录投放广告。您可以访问 <a href="https://adssettings.google.com" target="_blank" rel="noopener">Google 广告设置</a> 关闭个性化广告。更多信息请参阅 <a href="https://policies.google.com/privacy" target="_blank" rel="noopener">Google 隐私政策</a> 及 <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noopener">合作伙伴网站数据使用方式</a>。',
      'privacy.s3.p': '我们可能会使用收集、监控和分析信息的第三方服务：',
      'privacy.s4.h2': '4. 数据安全',
