      'privacy.s5.h2': '5. 儿童隐私',
      'privacy.s5.p': '我们的网站不适合 13 岁以下的儿童。我们不会故意收集 13 岁以下儿童的个人信息。如果您是父母或监护人，并认为您的孩子向我们提供了个人信息，请与我们联系。',
      'privacy.s6.h2': '6. 外部链接',
      'privacy.s6.p': '我们的网站可能包含指向非我们运营的外部网站的链接。我们无法控制这些网站的内容和实践，也不对其隐私政策负责。',
      'privacy.s7.h2': '7. 您的权利',
