      'prog.backpack.free.total': '<strong>📊 免费扩容合计：</strong>5 × 50 = <strong>+250 仓库格</strong>，全程无需任何操作，到等级自动到账。纯靠免费进度，仓库依次为 200 → 250 → 300 → 350 → <strong>400 格</strong>。背包也有自己的一条随 DG 等级增长的基础线（Lv.1 约 20 格、Lv.5 约 28、Lv.10 约 36、Lv.15 约 44、Lv.20 约 52），这还没算购买的部分。',
      'prog.backpack.heading': '🎒 背包 & 仓库扩容 · 完全指南',
      'prog.backpack.intro': '背包容量是游戏里最被低估的资源——格子不够就要在采集途中反复跑回家，等于把有效采集时间砍掉一半。扩容分免费和满愿星两条线，搭配得当收益最大。',
      'prog.backpack.kaChing': '<strong>📍 卡清位置：</strong>西北郊区、住宅街上，8 号地块对面，在她的杂货商店里。这个 NPC 同时负责背包券和仓库券。注意二者是<strong>两笔独立的购买</strong>——要分别买，折扣次数也分开算。常见建议是先把两种券各买满 5 张折扣（各 50 星）再考虑其他消费。',
      'prog.backpack.paid.budget': '<strong>💰 满愿星预算：</strong>满愿星主要来自每日 5 个居民委托（每个 5 星，一天最多 25 星），另有兑换码、活动和社区奖励。前期（DG 1-7）优先投进打折扩容 → 背包前 5 次（50 星）+ 仓库前 5 次（50 星）= 100 星 → 之后真正缺格子时再按 25 星一次次补。',
      'prog.backpack.paid.heading': '⭐ 许愿星扩容（付费途径）',
