      'prog.hobbies.order.o3.reason': '<strong>唯一能把其他产出成倍放大的爱好。</strong>果酱约为原料价值的 2.4-2.7 倍，多数其他菜品约 1.3-1.5 倍——但星级会在此之上叠加，5★ 菜品可以卖到 1★ 的数倍。正是这个组合让烹饪成为标准的首选。<br>捕虫和观鸟<em>并非</em>死路——虫卡和鸟卡都能卖给阿尔伯特二世——它们只是不具备放大效应。',
      'prog.hobbies.order.o3.wrong': '先选捕虫或观鸟不至于毁掉存档，但会把烹饪的放大效应推迟到 Lv.8——而金币最紧张的恰恰就是这段时间，你还要付种子、扩容和工具的钱。',
      'prog.hobbies.order.o4.hobby': '🦋 <strong>捕虫</strong>',
