      'prog.hobbies.order.o5.reason': '<strong>观鸟的特点是反复拍同一只鸟也照样累积进度</strong>——不必到处找新品种，可以蹲一个固定点安心刷。越稀有的动作星级越高。完成后五个产出/收集类爱好就全部解锁了。',
