      'prog.hobbies.order.o6.reason': '宠物系统的入口，也是养狗的硬性前置——不先解锁养猫，琼女士不会开放养狗。',
      'prog.hobbies.order.o6.wrong': '——（要消耗一张爱好扩展券，记得留一张）',
