      'prog.hobbies.order.th.reason': '选择理由',
      'prog.hobbies.order.th.wrong': '选了别的会怎样？',
      'prog.hobbies.overview.heading': '📋 7大爱好一览表',
      'prog.hobbies.th.dglevel': 'DG 等级',
