      'prog.hobbies.th.method': '解锁方式',
      'prog.hobbies.th.npc': '解锁 NPC',
      'prog.hobbies.th.npcloc': 'NPC 位置',
      'prog.hobbies.th.output': '核心产出',
      'prog.hobbies.th.type': '类型',
      'prog.hobbies.tips.bird.body': '• <strong>反复拍同一只鸟也照样累积进度</strong>——不必追着找新品种<br>• 找一个固定的鸟点安心刷<br>• 越稀有的姿势和动作，星级越高<br>• 观鸟卡可以交给贝莉，也可以卖给阿尔伯特二世换金币',
      'prog.hobbies.tips.bird.heading': '🔭 观鸟升级',
      'prog.hobbies.tips.bug.body': '• 充气蜜蜂诱虫器在捕虫 Lv.4 解锁——放下后约 60 秒内附近昆虫刷新大增，并有概率出稀有品种<br>• 不同季节和天气会出现不同的昆虫<br>• 5★ 标本可计入家园评定<br>• 捕虫商店出售拼图梦（Lv.16 之后用来升级梦境）',
      'prog.hobbies.tips.bug.heading': '🦋 捕虫升级',
      'prog.hobbies.tips.cooking.body': '• 主流摆法是<strong>三口锅呈 90° 摆放</strong>，站在中间不用走动就能全部照顾到；食物车的灶位更多（约 5-6 个）<br>• 批量做同一道菜，效率最高<br>• 值得主攻的高价配方：草莓酱、蓝莓酱、炸鱼薯条<br>• 烹饪等级 = 高星概率 ↑ = 售价 ↑',
      'prog.hobbies.tips.cooking.heading': '🍳 烹饪升级',
      'prog.hobbies.tips.fishing.body': '• 钓点与天气是配对的——晴天更适合霞光河等河钓点，雨天更适合浅水河与湖泊<br>• 每日 12:00 和 21:00 有限时海钓事件；海钓派对由比尔在渔村码头主持<br>• <strong>钓鱼等级越高 → 高星鱼概率越高 → 售价越高</strong>',
      'prog.hobbies.tips.fishing.heading': '🎣 钓鱼升级',
      'prog.hobbies.tips.gardening.body': '• 轮种速成作物（土豆：种子 30G，1 小时）→ 收得勤、经验也来得勤<br>• 别让地空着——收完立刻补种<br>• 高级花卉（玫瑰、百合）在家园评定里比基础花卉加分高得多<br>• <strong>园艺等级会提高收获物的星级</strong>',
      'prog.hobbies.tips.gardening.heading': '🌱 园艺升级',
      'prog.hobbies.tips.heading': '📈 各爱好升级技巧',
      'prog.hobbies.tips.pets.body': '• 每日互动（喂食、抚摸、逗弄/训练）会提升宠物的成长值和等级<br>• 必须先解锁养猫，琼女士才会开放养狗<br>• 猫狗可以同养——最多 5 只猫、3 只狗<br>• 宠物每升一级都会发放金币和满愿星',
      'prog.hobbies.tips.pets.heading': '🐱🐕 宠物升级',
      'prog.house.advanced.heading': '🎨 打开高级建造模式，正式装修',
      'prog.house.advanced.p1': '在「设置 → 玩法设置」里打开高级建造，整个装修效率会显著提升。建议顺序：',
      'prog.house.advanced.p2': '<strong>装修流程：</strong><br>① <strong>先定户型：</strong>确定每个区域的功能（厨房区、卧室区、藏品展示、宠物角）<br>② <strong>墙与地板：</strong>批量铺地板 → 批量砌墙分隔区域<br>③ <strong>屋顶线条：</strong>把屋顶部件按不同高度堆叠、错落摆放，别让房子成为一个扁盒子——但要注意承重上限<br>④ <strong>家具布局：</strong>按功能摆放，用多选一次移动整组家具<br>⑤ <strong>细节收尾：</strong>挂画、摆件、绿植、灯光——这些细节决定质感',
      'prog.house.advanced.p3': '<strong>核心原则：</strong>建造界面有撤销按钮——大胆试布局，不满意就回退。多去好友家逛逛并截图存灵感。',
      'prog.house.blueprint.heading': '🏗️ 前期：先把功能搭起来，别急着好看',
      'prog.house.blueprint.p1': '在收入稳定、仓库有货之前，<strong>别把大把时间砸进装修</strong>。一格一格摆很慢，而同样一面墙，打开高级建造模式后一次拖拽就搞定。',
      'prog.house.blueprint.p2': '<strong>前期只做这些：</strong><br>① 摆功能家具：床、锅灶、储物箱、工作台<br>② 保持室内开阔——给以后的设计留空间<br>③ 先画户型草图（纸上或截图标注），再决定投材料<br>④ 收集灵感：多去好友家逛，把喜欢的布局截图存下来',
      'prog.house.blueprint.p3': '<strong>核心原则：</strong>前期的金币和时间应该投在生产上（种子、锅灶、扩容），而不是纯装饰。',
      'prog.house.compare.heading': '🔷 基础摆放 vs 高级（上帝视角）建造',
      'prog.house.compare.r1.advanced': '设置 → 玩法设置里开启（仅单人模式）',
