      'prog.house.compare.r3.advanced': '✅ <strong>批量操作</strong>——多选后可一次性建造、粉刷或拆除大片区域',
      'prog.house.compare.r3.blueprint': '逐块铺设，速度慢',
      'prog.house.compare.r3.feature': '<strong>铺设地板</strong>',
      'prog.house.compare.r4.advanced': '✅ <strong>俯视上帝视角</strong>——可平移、旋转、缩放，并逐层隐藏「切开」房子看内部',
      'prog.house.compare.r4.blueprint': '普通第三人称视角',
