      'prog.house.compare.r6.advanced': '✅ 多选——同一平面的家具可以整体移动或整体收起',
      'prog.house.compare.r6.blueprint': '逐个放置，手动调整',
      'prog.house.compare.r6.feature': '<strong>家具放置</strong>',
      'prog.house.compare.r8.advanced': '完整装修、冲家园评定、大型建造',
      'prog.house.compare.r8.blueprint': '摆放基础功能家具（床、锅灶、储物箱）',
      'prog.house.compare.r8.feature': '<strong>适用场景</strong>',
      'prog.house.compare.th.advanced': '🔶 高级（上帝视角）',
      'prog.house.compare.th.blueprint': '🔷 基础摆放',
      'prog.house.compare.th.feature': '功能',
      'prog.house.eyebrow': '家园系统',
      'prog.house.heading': '🏠 房屋建造系统 · 详解',
      'prog.house.intro': '心动小镇开局就有基础摆放模式，另有一个需要你自己打开的高级「上帝视角」建造模式。高级模式不是按 DG 等级解锁的——它是「设置 → 玩法设置」里的开关（单人模式下也可以点右上角按钮切换，多人模式无法开启）。蓝图约在 DG Lv.8 开放。',
      'prog.house.tips.heading': '💡 房屋建造进阶技巧',
      'prog.house.tips.iter.body': '① 先把「框架」搭出来——墙的位置和房间尺寸<br>② 进屋走一圈感受比例——太大显空，太小显挤<br>③ 反复撤销重建，直到比例舒服为止<br>④ 最后再加家具和装饰——细节永远放在最后一步<br><strong>别想一次定稿——好布局都是迭代出来的。</strong>',
      'prog.house.tips.iter.heading': '🔄 迭代设计法',
      'prog.house.tips.open.body': '<strong>开放式</strong>（少墙或无内墙）：空间感强，适合展示大量藏品，视线通透。适合新手——墙少，出错也少。<br><strong>隔间式</strong>（多房间）：功能分区清晰、私密性更好，适合做主题设计（厨房、书房、阳光房）。批量砌墙能让这件事轻松很多。',
      'prog.house.tips.open.heading': '🏗️ 开放式 vs 隔间式',
      'prog.house.tips.roof.body': '① <strong>堆叠与错落：</strong>游戏里没有屋顶「合并」功能——要打破盒子感，靠的是把屋顶部件按不同高度堆叠、重叠摆放<br>② <strong>注意承重上限：</strong>结构堆得太满反而会在家园评定里扣分<br>③ <strong>配色：</strong>屋顶与墙面配色要协调——深色屋顶配浅色墙面是稳妥组合',
      'prog.house.tips.roof.heading': '📐 屋顶设计技巧',
      'prog.house.tips.score.body': '家园评定约在 <strong>DG Lv.12</strong> 解锁。每周提交一次（周六截止，周六凌晨出结果），系统保留历史最高分，所以可以重新装修后再提交。<br>• <strong>「种类多样性」才是评分核心</strong>——某件物品第一次摆放约 100 分，重复的只有约 1 分<br>• 家具按品类分别计分；付费家具与活动家具分值更高<br>• 5★ 收藏品（昆虫标本、鱼）和成品菜肴都计分<br>• 花卉按等级<em>和</em>种类计分——把基础花换成高级花是一次大幅提分<br>• 注意：宠物<strong>不会</strong>计入家园评定分数',
      'prog.house.tips.score.heading': '⭐ 家园评定，以及怎么拿高分',
