      'prog.pets.care.affection.body': '• 抚摸、喂食、玩耍都会提升宠物的成长值；每达到新的宠物等级会发放金币和满愿星<br>• 等级越高，解锁的互动动作越多<br>• 每只宠物的进度<strong>各自独立</strong>——猫和狗不共享<br>• 漏一天不会损失已获得的进度，掉的只是饱食度和心情',
