      'prog.pets.faq.a1': '<strong>不能。</strong>养猫是硬性前置。DG Lv.12 解锁养猫 → 领养一只 → 完成任务「学习新爱好」→ 再交一张爱好扩展券给琼女士，养狗就会在<strong>同一个 DG 等级</strong>开放。不存在 Lv.14 这道门槛。',
      'prog.pets.faq.a2': '<strong>可以！</strong>两个爱好都解锁后，最多可同时养 5 只猫和 3 只狗——合计 8 只。每只的成长进度独立，互不影响。猫的位置在养猫 Lv.1/2/5/7/9 依次开放，狗的位置在养狗 Lv.1/4/8 开放。',
      'prog.pets.faq.a3': '不会掉进度。<strong>成长值和宠物等级不会倒退</strong>，漏一天只是当天没有增长而已。真正会掉的是饱食度和心情——又饿又不开心的宠物更容易拒绝互动，所以回来后记得补上。',
      'prog.pets.faq.a4': '宠物每升一级会发放<strong>金币和满愿星</strong>，并解锁更多互动动作。另有「猫咪时刻 / 狗狗时刻」图鉴（1-5★），集齐星数可兑换金币、满愿星和家具制作书。宠物服装确实存在（头套和衣服两个部位），但它来自宠物时装店和琼女士的商店，并不是满级奖励。注意宠物<strong>不会</strong>为家园评定加分。',
      'prog.pets.faq.a5': '不会。宠物系统和 Dream（DG Lv.16）是完全独立的两个系统，互不影响。你可以同时养宠物和升级 Dream。',
